import Database from 'better-sqlite3';

let db: Database.Database | null = null;

export function getDb() {
  if (!db) {
    db = new Database('/home/user/qwik-app/poll.db', { timeout: 5000 });
    // Enable WAL mode for high concurrency and performance
    db.pragma('journal_mode = WAL');
  }
  return db;
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getDb } from '../../../../lib/db.server';

export const onPost: RequestHandler = async (event) => {
  const pollId = event.params.id;

  let body: any;
  try {
    body = await event.request.json();
  } catch (e) {
    throw event.json(400, { error: 'Invalid option ID' });
  }

  if (!body || typeof body.optionId !== 'number') {
    throw event.json(400, { error: 'Invalid option ID' });
  }

  const optionId = body.optionId;
  const db = getDb();

  // Extract client IP
  const xForwardedFor = event.request.headers.get('x-forwarded-for');
  let ip = '';
  if (xForwardedFor) {
    ip = xForwardedFor.split(',')[0].trim();
  } else {
    ip = event.clientConn?.ip || '127.0.0.1';
  }

  const now = Date.now();

  let result: { success?: boolean; error?: string };
  try {
    result = db.transaction(() => {
      // 1. Check if poll exists
      const poll = db.prepare('SELECT id FROM polls WHERE id = ?').get(pollId);
      if (!poll) {
        return { error: 'not_found' };
      }

      // 2. Check if option exists and belongs to the poll
      const option = db.prepare('SELECT id, poll_id FROM options WHERE id = ?').get(optionId);
      if (!option || option.poll_id !== pollId) {
        return { error: 'not_found' };
      }

      // 3. Check rate limit (1 vote per 5 seconds per poll per IP)
      const limitTime = now - 5000;
      const recentVote = db.prepare(
        'SELECT 1 FROM votes_log WHERE poll_id = ? AND ip = ? AND timestamp >= ? LIMIT 1'
      ).get(pollId, ip, limitTime);

      if (recentVote) {
        return { error: 'rate_limit' };
      }

      // 4. Record vote log
      db.prepare('INSERT INTO votes_log (poll_id, ip, timestamp) VALUES (?, ?, ?)')
        .run(pollId, ip, now);

      // 5. Increment vote count
      db.prepare('UPDATE options SET votes = votes + 1 WHERE id = ?')
        .run(optionId);

      return { success: true };
    })();
  } catch (err: any) {
    throw event.json(500, { error: err.message || 'Internal Server Error' });
  }

  if (result.error === 'not_found') {
    throw event.json(404, { error: 'Poll or option not found' });
  }

  if (result.error === 'rate_limit') {
    throw event.json(429, { error: 'Rate limit exceeded' });
  }

  // Success! Fetch updated vote counts for all options of that poll
  let options: { id: number; votes: number }[];
  try {
    options = db.prepare('SELECT id, votes FROM options WHERE poll_id = ?').all(pollId) as { id: number; votes: number }[];
  } catch (err: any) {
    throw event.json(500, { error: err.message || 'Internal Server Error' });
  }

  const votesObj: Record<string, number> = {};
  for (const opt of options) {
    votesObj[String(opt.id)] = opt.votes;
  }

  throw event.json(200, {
    success: true,
    votes: votesObj
  });
};

import { component$, useStore, $, useTask$ } from '@builder.io/qwik';
import { routeLoader$ } from '@builder.io/qwik-city';
import { getDb } from '../../../lib/db.server';

export const usePollData = routeLoader$(async (event) => {
  const pollId = event.params.id;
  const db = getDb();

  // 1. Fetch poll
  const poll = db.prepare('SELECT * FROM polls WHERE id = ?').get(pollId) as { id: string; question: string } | undefined;
  if (!poll) {
    throw event.text(404, 'Poll not found');
  }

  // 2. Fetch options
  const options = db.prepare('SELECT * FROM options WHERE poll_id = ?').all(pollId) as {
    id: number;
    poll_id: string;
    text: string;
    votes: number;
  }[];

  return {
    poll,
    options,
  };
});

export default component$(() => {
  const pollData = usePollData();

  const state = useStore({
    options: pollData.value.options,
    error: '',
  });

  useTask$(({ track }) => {
    track(() => pollData.value);
    state.options = pollData.value.options;
    state.error = '';
  });

  const handleVote = $(async (optionId: number) => {
    state.error = '';
    try {
      const response = await fetch(`/poll/${pollData.value.poll.id}/vote`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ optionId }),
      });

      const data = await response.json();

      if (response.ok && data.success) {
        state.options = state.options.map((opt) => ({
          ...opt,
          votes: data.votes[String(opt.id)] ?? opt.votes,
        }));
      } else {
        state.error = data.error || 'Failed to cast vote';
      }
    } catch (err: any) {
      state.error = 'An error occurred while voting.';
    }
  });

  const totalVotes = state.options.reduce((sum, opt) => sum + opt.votes, 0);

  return (
    <div style={{ maxWidth: '600px', margin: '40px auto', padding: '0 20px', fontFamily: 'sans-serif' }}>
      <h1 id="poll-question" style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '20px' }}>
        {pollData.value.poll.question}
      </h1>

      <div style={{ marginBottom: '30px' }}>
        <svg id="poll-chart" width="500" height="300" style={{ background: '#f9f9f9', borderRadius: '8px', border: '1px solid #eee' }}>
          {state.options.map((option, index) => {
            const percentage = totalVotes > 0 ? option.votes / totalVotes : 0;
            const width = percentage * 400;
            const barHeight = 24;
            const spacing = 45;
            const startY = 40;
            const y = startY + index * spacing;

            return (
              <g key={option.id}>
                {/* Option Label inside SVG */}
                <text
                  x="15"
                  y={y - 6}
                  style={{ fontSize: '12px', fill: '#555', fontWeight: 'bold' }}
                >
                  {option.text}
                </text>
                {/* Bar */}
                <rect
                  class="chart-bar"
                  data-option-id={option.id}
                  x="15"
                  y={y}
                  width={width}
                  height={barHeight}
                  fill="#3b82f6"
                  rx="4"
                  style={{ transition: 'width 0.3s ease' }}
                />
                {/* Vote Count */}
                <text
                  class="vote-count"
                  data-option-id={option.id}
                  x={15 + width + 8}
                  y={y + barHeight / 2 + 4}
                  style={{ fontSize: '12px', fill: '#333', fontWeight: 'bold' }}
                >
                  {option.votes}
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      {state.error && (
        <div id="error-message" style={{ color: '#ef4444', backgroundColor: '#fee2e2', padding: '10px 15px', borderRadius: '6px', marginBottom: '20px', fontSize: '14px' }}>
          {state.error}
        </div>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {state.options.map((option) => (
          <button
            key={option.id}
            class="vote-button"
            data-option-id={option.id}
            onClick$={() => handleVote(option.id)}
            style={{
              padding: '12px 20px',
              fontSize: '16px',
              fontWeight: '500',
              color: '#fff',
              backgroundColor: '#2563eb',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              transition: 'background-color 0.2s',
              textAlign: 'left',
            }}
          >
            Vote for {option.text}
          </button>
        ))}
      </div>
    </div>
  );
});

